const dicts = { zh, en };
let lang = localStorage.getItem('m-ui-lang') || (navigator.language.startsWith('zh') ? 'zh' : 'en');

export function t(key, vars) {
  let s = (dicts[lang] && dicts[lang][key]) ?? zh[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replace('{' + k + '}', v);
  return s;
}
export function getLang() { return lang; }
export function setLang(l) { if (dicts[l]) { lang = l; localStorage.setItem('m-ui-lang', l); } }
export const langs = { zh: '中文', en: 'English' };
